fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let text=std::fs::read_to_string(&args[2]).unwrap();let mut results=Vec::new();for line in text.lines().filter(|l|!l.trim().is_empty()&&!l.starts_with('#')){let v:Vec<_>=line.split_whitespace().collect();let start:usize=v[0].parse().unwrap();let end:usize=v[1].parse().unwrap();assert!(start<end&&end<=ops.len());let r=shadow_value_contract(&ops[start..end],500000,2000);results.push(serde_json::json!({"start":start,"end_exclusive":end,"proved":r.proved,"status":r.status,"quantum_ids":r.quantum_ids,"choices_zero_or_reset":r.choices,"classical_wires":r.classical_wires,"ops":r.ops,"mr":r.mr,"nodes":r.nodes,"caps":r.caps,"unresolved":r.unresolved,"seconds":r.seconds}));}println!("{}",serde_json::json!({"source_stream":args[1],"full_operation_count":ops.len(),"results":results,"status":"UNIVERSAL_LOCAL_ZERO_MR_OR_RESET_CONTRACT_ONLY_NO_GLOBAL_SKIP"}));}
